import type { Chapter, Topic } from "@/lib/study/schema";

/**
 * Computer Organisation → I/O interface: interrupts and DMA (Hamacher, Hennessy and Patterson, Stallings; GATE CS syllabus: "I/O interface (interrupt and DMA mode)").
 * Numbers from lib/study/io-hw.ts, checked by scripts/io-hw-check.ts (500 MHz CPU):
 * polling 400 cycles: mouse (30 polls/s) 0.0024%; floppy 50 KB/s in 2-byte chunks 2%; disk 4 MB/s in 16-byte chunks = 250,000 polls/s = 20%.
 * interrupts of 500 cycles: the disk 25% when always busy, 1.25% when busy 5% of the time. DMA, 8 KB blocks, 1000 set-up + 500 completion cycles: 0.146% (0.0073% at 5% busy).
 * cycle stealing: 1 MB/s in 2-byte words with a 500 ns memory cycle steals 25% of the memory cycles; 4 MB/s in 4-byte words with 100 ns: 10%. A 1024-word burst at 100 ns locks the CPU out for 102.4 µs.
 * a 500-cycle handler at 500 MHz allows at most 1,000,000 interrupts a second. Daisy chain with devices 1 and 3 requesting: device 1 wins. Bus 32-bit at 100 MHz: 400 MB/s; with an address cycle per word 200 MB/s; 8-word bursts with one address cycle 355.6 MB/s.
 */
const TP = "/topics/computer-organization-and-architecture-coa";
const HREF = "/study/io-interrupts-dma";

/* ------------------------------------------------------------------ 1. I/O organisation and programmed I/O */
const orgT: Topic = {
  id: "cs.coa.ioorg",
  title: "I/O organisation: the interface, I/O addressing and programmed I/O",
  blocks: [
    { type: "hook", text: "A processor that cannot talk to a keyboard, a disk or a network card is only a calculator. But those devices are thousands of times slower than the processor, they run on their own clocks, and they speak in bits, bytes and blocks of their own. The I/O interface is the translator between the two worlds, and the first design question is how the processor should wait for a slow device." },
    { type: "objectives", items: ["Describe an I/O interface with its data, status and control registers.", "Compare memory-mapped and isolated I/O addressing.", "List the three ways to transfer data: programmed I/O, interrupt-driven I/O and DMA.", "Compute the CPU time that polling takes for a given device."] },
    { type: "intuition", paras: ["Each device is attached through an interface (a controller) that looks to the processor like a few registers. A data register holds the byte or word being moved, a status register tells whether the device is ready or busy or has an error, and a control register lets the processor start an operation or change a setting. To the program, doing I/O means reading and writing those registers.", "How does the processor reach them? In memory-mapped I/O the registers are given ordinary addresses in the same address space as memory, so the ordinary load and store instructions do I/O, and no special instructions are needed; the price is that some addresses are no longer available for memory. In isolated (port-mapped) I/O there is a separate address space for devices, reached with special IN and OUT instructions and signalled by a control line (IO/M); memory addresses are not used up, but extra instructions and signals are needed.", "The simplest way to wait is programmed I/O: the program reads the status register in a loop until the ready bit is set, then moves the data. This is polling or busy waiting. It is simple, but while it loops the processor does nothing else, and a fast processor spends its time asking a slow device the same question."] },
    { type: "definition", name: "I/O transfer methods", text: "Three ways to move data between a device and memory:", items: ["Programmed I/O (polling): the CPU tests the status register in a loop and transfers every word itself.", "Interrupt-driven I/O: the device interrupts the CPU when it is ready; the CPU runs a handler that moves the word, then goes back to its work.", "Direct memory access (DMA): a DMA controller moves a whole block between the device and memory on its own and interrupts the CPU only once, at the end.", "Memory-mapped I/O: device registers share the memory address space (load/store). Isolated I/O: a separate port space (IN/OUT).", "CPU share of polling = (polls per second × cycles per poll) / clock rate; a device delivering R bytes/s in chunks of c bytes must be polled R / c times a second."] },
    { type: "deep", sections: [
      { h: "The I/O interface", paras: ["An interface has to do several jobs. It decodes the device's address (the processor puts an address on the bus and only the matching interface responds). It converts between the bus's parallel word and the device's format (serial bits for a keyboard or a network, blocks for a disk). It buffers data, because the device and the bus run at different speeds. It provides status and control so the program can see and direct what happens, and it can raise an interrupt request when the device needs attention.", "A typical program for a keyboard reads the status register and tests bit 0, loops while it is 0, then reads the data register, which also clears the ready bit. For a printer the test is on a 'ready for data' bit, and the program writes a character to the data register, which starts printing and clears the ready bit until the printer is done."] },
      { h: "Memory-mapped against isolated I/O", paras: ["With memory-mapped I/O every instruction that can touch memory can touch a device, including arithmetic on a register or a bit test directly on the device. It also needs no separate IO/M line. But part of the address space is taken, and device registers must not be cached (their values change by themselves).", "With isolated I/O, a 16-bit port address space needs only a few instructions (IN, OUT) and the full memory space stays free for memory. Many older microprocessors (Intel 8085, x86) have both; most RISC machines (MIPS, ARM, RISC-V) are memory mapped."] },
      { h: "What polling costs", paras: ["Take a 500 MHz processor and assume that one poll (the test and the loop around it, plus the operating-system overhead) costs 400 cycles. A mouse must be polled about 30 times a second so as not to lose movement: 30 × 400 = 12,000 cycles a second, 0.0024% of the processor, which is nothing. A floppy disk delivering 50 KB/s in 2-byte chunks needs 25,000 polls a second: 25,000 × 400 = 10 million cycles, 2%. A hard disk delivering 4 MB/s in 16-byte chunks needs 250,000 polls a second: 100 million cycles, 20% of the processor, all of it wasted when the disk is not actually transferring, since the program has to keep asking.", "Polling therefore suits slow devices and simple systems (and cases where the processor has nothing else to do, or must respond with fixed timing). For fast devices it is too expensive, which is why interrupts and DMA exist."] },
    ] },
    { type: "walkthrough", steps: ["Find how often the device must be serviced: rate in bytes per second divided by the bytes taken per service.", "Multiply by the cycles one service costs: that is cycles per second spent on I/O.", "Divide by the clock rate to get the fraction of the CPU.", "For polling the device is asked all the time, whether it is busy or not.", "Compare with the other methods before choosing."], prompt: { q: "What is the main difference between memory-mapped and isolated I/O?", a: "Memory-mapped I/O uses the memory address space and ordinary load and store instructions; isolated I/O has its own address space and special IN and OUT instructions." } },
    { type: "figure", id: "poll-tbl", for: "ex1", caption: "CPU time used by polling at 500 MHz, 400 cycles per poll.", alt: "Mouse 30 polls a second 0.0024 percent, floppy 25,000 polls 2 percent, disk 250,000 polls 20 percent.", fig: { kind: "matrix", title: "Polling cost", cols: ["rate", "polls / second", "CPU used"], rows: [{ label: "Mouse", cells: ["—", 30, "0.0024%"] }, { label: "Floppy disk", cells: ["50 KB/s, 2 B chunks", 25000, "2%"] }, { label: "Hard disk", cells: ["4 MB/s, 16 B chunks", 250000, "20%"], hl: true }] } },
    { type: "figure", id: "map-tbl", for: "ex2", caption: "The two ways of addressing devices.", alt: "Memory-mapped I/O uses the memory space and load and store; isolated I/O has a separate space with IN and OUT and an IO/M line.", fig: { kind: "matrix", title: "I/O addressing", cols: ["address space", "instructions", "cost"], rows: [{ label: "Memory-mapped", cells: ["shared with memory", "load / store", "uses up addresses"], hl: true }, { label: "Isolated (port-mapped)", cells: ["separate", "IN / OUT", "extra instructions and an IO/M line"] }] } },
    { type: "example", id: "ex1", level: "gate", title: "The cost of polling a disk", given: "A 500 MHz CPU polls a disk that delivers 4 MB/s in 16-byte chunks. A poll costs 400 cycles.", find: "The polls per second and the CPU fraction used.",
      steps: [{ say: "Polls per second = 4,000,000 / 16.", result: "250,000" }, { say: "Cycles per second = 250,000 × 400.", result: "100,000,000" }, { say: "Fraction = 100 M / 500 M.", result: "20%" }],
      answer: "250,000 polls a second, 20% of the CPU.", check: "Use the disk preset in the polling, interrupts and DMA lab." },
    { type: "example", id: "ex2", level: "gate", title: "Memory-mapped addressing", given: "A machine has a 16-bit address bus. Memory-mapped I/O reserves the addresses FF00 to FFFF for devices.", find: "How many addresses remain for memory, and how many device registers can be addressed.",
      steps: [{ say: "Addresses 0000 to FFFF: 2¹⁶ = 65,536.", result: "65,536" }, { say: "FF00 to FFFF is 256 addresses reserved for devices.", result: "256 for I/O" }, { say: "Memory keeps 65,536 − 256.", result: "65,280" }],
      answer: "65,280 addresses for memory; 256 device registers.", check: "With isolated I/O all 65,536 addresses stay available for memory." },
    { type: "example", id: "ex3", level: "edge", title: "A slow device", given: "A keyboard produces 10 characters a second. The 500 MHz CPU polls it 10 times a second, each poll costing 400 cycles.", find: "The CPU fraction used.",
      steps: [{ say: "10 × 400 = 4,000 cycles a second.", result: "4,000" }, { say: "4,000 / 500,000,000.", result: "0.0008%" }],
      answer: "0.0008%: polling is perfectly good for a keyboard.", check: "The cost depends on the poll rate, not on how fast the CPU is." },
    { type: "lab", lab: "io-compare" },
    { type: "faded", title: "Your turn", given: "A 1 GHz CPU polls a device that delivers 2 MB/s in 8-byte chunks. A poll costs 500 cycles.", steps: [{ say: "Polls per second?", blank: true, answer: "2,000,000 / 8 = 250,000." }, { say: "Cycles per second?", blank: true, answer: "250,000 × 500 = 125,000,000." }, { say: "CPU fraction?", blank: true, answer: "125 M / 1000 M = 12.5%." }] },
    { type: "trap", wrong: "Polling costs CPU time only when the device has data.", tempting: "The loop is for waiting.", whyWrong: "The program must keep testing whether or not the device is ready, so the cost is paid all the time at the poll rate.", rule: "Polling cost = poll rate × cycles per poll, busy or idle." },
    { type: "trap", wrong: "Isolated I/O gives a bigger address space for the devices.", tempting: "It has its own space.", whyWrong: "It gives memory the whole address space back; the device space is a separate, usually small, port space.", rule: "Isolated I/O saves memory addresses; memory-mapped saves instructions." },
    { type: "trap", wrong: "Device registers can be cached like memory.", tempting: "Memory-mapped registers look like memory.", whyWrong: "A device register changes by itself and reads can have side effects (clearing a ready bit), so it must never be cached.", rule: "Memory-mapped I/O regions are non-cacheable." },
    { type: "shortcut", text: "Service rate = byte rate / chunk. CPU fraction = service rate × cycles per service / clock. Polling is paid all the time; interrupts and DMA are paid only when the device is active.", validWhen: "One device, constant rate, the same cycle count for every service." },
    { type: "gate", text: "GATE asks for the CPU time or the percentage of CPU used by polling for a device, the difference between memory-mapped and isolated I/O, the roles of the status and data registers, and when each of the three transfer modes is appropriate. I/O questions appear most years." },
    { type: "recall", cards: [{ q: "Status register", a: "tells if the device is ready, busy or in error" }, { q: "Memory-mapped I/O", a: "devices in the memory space, load/store" }, { q: "Isolated I/O", a: "separate port space, IN/OUT, IO/M line" }, { q: "Polling cost", a: "polls/s × cycles per poll / clock" }, { q: "Polling is good for", a: "slow devices, simple systems" }] },
    { type: "check", questions: [
      { id: "io1", kind: "NAT", marks: 1, q: "A device delivers 4 MB/s in 16-byte chunks and must be polled once per chunk. How many polls per second (in thousands)?", answer: "250", solution: "4,000,000 / 16 = 250,000." },
      { id: "io2", kind: "NAT", marks: 2, q: "A 500 MHz processor polls a disk delivering 4 MB/s in 16-byte chunks; a poll takes 400 cycles. What percentage of the CPU is used?", answer: "20", solution: "250,000 × 400 / 500,000,000." },
      { id: "io3", kind: "NAT", marks: 2, q: "A 1 GHz processor polls a device delivering 2 MB/s in 8-byte chunks, 500 cycles a poll. What percentage of the CPU is used?", answer: "12.5", solution: "250,000 × 500 / 10⁹." },
      { id: "io4", kind: "MCQ", marks: 1, q: "In memory-mapped I/O", options: ["Devices use a separate address space", "Ordinary load and store instructions access device registers", "Special IN and OUT instructions are required", "An IO/M control line is required"], answer: "B", solution: "Devices share the memory address space." },
      { id: "io5", kind: "MSQ", marks: 2, q: "Which are true of programmed I/O?", options: ["The CPU tests a status register in a loop", "It wastes CPU time on fast devices", "The device interrupts the CPU when ready", "The CPU transfers every word"], answer: "A, B, D", solution: "Interrupts belong to interrupt-driven I/O." },
    ] },
    { type: "practice", links: [{ label: "Real GATE questions on Computer Organisation", sub: "I/O interface", href: TP }, { label: "Topic 2: interrupts", sub: "Vectors and priority", href: HREF }, { label: "Topic 3: DMA", sub: "Modes and cost", href: HREF }] },
    { type: "links", prereq: ["Bus and memory addressing", "CPU clock rate"], usedIn: ["Interrupts", "DMA", "Device drivers (OS)"], cross: ["OS: device drivers", "CN: network interface cards"] },
  ],
};

/* ------------------------------------------------------------------ 2. Interrupts */
const irqT: Topic = {
  id: "cs.coa.irq",
  title: "Interrupts: handling, vectors, priority and daisy chains",
  blocks: [
    { type: "hook", text: "Waiting in a loop for a device is like standing at the door until the delivery arrives. An interrupt is the doorbell: the processor goes on with its work, the device rings when it needs attention, and the processor drops what it is doing for a moment, deals with the visitor, and returns exactly to where it was. Almost everything an operating system does in response to the outside world starts with one." },
    { type: "objectives", items: ["Describe what happens from an interrupt request to the return from the handler.", "Distinguish maskable, non-maskable, vectored, software and exception interrupts.", "Explain how priority is resolved with a daisy chain and with a priority controller.", "Compute the CPU cost of interrupt-driven I/O and the highest interrupt rate a CPU can sustain."] },
    { type: "intuition", paras: ["When a device is ready it raises an interrupt request line. The processor does not stop at once: it finishes the instruction in progress (so that no instruction is left half done), and then, if interrupts are enabled, it acknowledges the request. It saves the program counter and the status, so that it can return; it finds the address of the right handler; and it jumps there. The interrupt service routine (ISR) talks to the device, moves the data, clears the request, and ends with a return-from-interrupt instruction that restores the saved state.", "Which handler? In a non-vectored system there is one fixed address, and the handler first has to poll the devices to find who rang. In a vectored system the device sends a vector (a number) when its request is acknowledged, and the processor uses it to index a table of handler addresses (the interrupt vector table), so the right routine is reached at once.", "Several devices can ring together, so priority is needed. The processor can mask (ignore) interrupts below a certain level while it is busy with something urgent; and an interrupt of higher priority may interrupt a running handler of lower priority (nested interrupts)."] },
    { type: "definition", name: "Interrupt terms", text: "Kinds and mechanisms:", items: ["Hardware interrupt: from a device, asynchronous to the program. Maskable (can be disabled by a mask or the interrupt-enable flag) or non-maskable (NMI: power failure, memory error, cannot be ignored).", "Software interrupt, trap or exception: caused by the program: a system call (trap), divide by zero, page fault, illegal instruction. Synchronous with the instruction.", "Vectored interrupt: the device supplies a vector that selects the handler. Non-vectored: one entry; software must find the source.", "Priority: fixed by the position in a daisy chain, or by a priority encoder in an interrupt controller; a mask register enables or disables each source.", "Cost of one interrupt: save and restore state, run the handler, return; often hundreds of cycles. The CPU time of interrupt-driven I/O = (interrupts per second × cycles per interrupt) / clock, paid only while the device is active."] },
    { type: "deep", sections: [
      { h: "The sequence in order", paras: ["1. The device asserts its interrupt-request line (IRQ). 2. The processor completes the current instruction. 3. If interrupts are enabled and the source is not masked, it asserts interrupt acknowledge (INTA). 4. It pushes the PC and the status word onto the stack (or saves them in special registers) and disables further interrupts of this level. 5. It obtains the handler address, from a fixed place or from the vector the device places on the data bus. 6. The handler runs: it saves any registers it will use, services the device, and clears the cause. 7. A return-from-interrupt instruction restores the status and PC, and the program resumes as if nothing had happened.", "In a pipelined processor the interrupt must be precise: the instructions before the interrupted one must have completed and those after it must not have changed anything, so that the handler can return to the right place."] },
      { h: "Priority with a daisy chain", paras: ["In a daisy-chain scheme all devices share one interrupt-request line. When the processor acknowledges, the INTA signal enters the first device and is passed from device to device along the chain. The first device that has a pending request keeps the acknowledge (and puts its vector on the bus) and does not pass it on. The device nearest the processor therefore has the highest priority: if devices 1 and 3 are both requesting, device 1 gets the acknowledge. It is cheap (one request line) but gives a fixed priority, so a busy high-priority device can starve the others, and a broken device in the chain can cut off all those behind it.", "A parallel scheme gives each device its own request line to a priority controller (an interrupt controller such as the 8259) that applies a mask and selects the highest-priority pending request, whose vector it supplies. It is faster and the priority can be programmed, at the cost of more lines and a controller."] },
      { h: "What interrupts cost", paras: ["Suppose each interrupt costs 500 cycles on a 500 MHz processor. The disk that delivers 4 MB/s in 16-byte chunks interrupts 250,000 times a second, which would use 250,000 × 500 = 125 million cycles, 25% of the processor while it is transferring. If the disk is active only 5% of the time the average cost is 0.05 × 25% = 1.25%, much better than polling's 20% which is paid all the time. For a very fast device the interrupt rate itself becomes the problem: the same processor can take at most 500 M / 500 = 1,000,000 such interrupts a second. That is why fast devices are given DMA, which interrupts once per block rather than once per word."] },
    ] },
    { type: "walkthrough", steps: ["Find the interrupt rate: byte rate divided by the bytes handled per interrupt.", "Multiply by the cycles per interrupt, and by the fraction of time the device is active.", "Divide by the clock: the CPU fraction used.", "To decide who is served first, apply the priority: nearest in the chain, or highest in the controller.", "Check that the interrupt rate is below the ceiling of clock / cycles per interrupt."], prompt: { q: "With a daisy chain, which device has the highest priority?", a: "The one nearest the processor, because the acknowledge reaches it first and it keeps it if it is requesting." } },
    { type: "figure", id: "irq-tbl", for: "ex1", caption: "The disk of the earlier topic with interrupts, 500 cycles each, 500 MHz.", alt: "Always busy 25 percent; busy 5 percent of the time 1.25 percent; polling for comparison 20 percent.", fig: { kind: "matrix", title: "CPU used", cols: ["always busy", "busy 5% of the time"], rows: [{ label: "Polling (400 cycles)", cells: ["20%", "20%"] }, { label: "Interrupts (500 cycles)", cells: ["25%", "1.25%"], hl: true }, { label: "DMA (8 KB blocks)", cells: ["0.146%", "0.0073%"] }] } },
    { type: "figure", id: "chain-tbl", for: "ex2", caption: "A daisy chain of four devices: who gets the acknowledge.", alt: "Devices 1 and 3 request; device 1 receives the grant and device 3 never sees it. If only device 3 requests, the grant passes all four.", fig: { kind: "matrix", title: "Requests and the winner", cols: ["requesting", "winner", "devices passed"], rows: [{ label: "1 and 3", cells: ["1, 3", "device 1", 2], hl: true }, { label: "only 3", cells: ["3", "device 3", 4] }, { label: "none", cells: ["—", "nobody", 4] }] } },
    { type: "example", id: "ex1", level: "gate", title: "Interrupt cost", given: "A 500 MHz CPU handles a disk delivering 4 MB/s in 16-byte chunks by interrupts of 500 cycles each. The disk is active 5% of the time.", find: "The CPU fraction when the disk is active, and on average.",
      steps: [{ say: "Interrupts per second = 4,000,000 / 16 = 250,000.", result: "250,000" }, { say: "Cycles per second = 250,000 × 500 = 125 million: 25% while active.", result: "25%" }, { say: "Average = 5% × 25%.", result: "1.25%" }],
      answer: "25% while the disk is transferring; 1.25% on average.", check: "Compare with the 20% of polling in the lab." },
    { type: "example", id: "ex2", level: "gate", title: "Daisy-chain priority", given: "Four devices 0 to 3 are on a daisy chain, device 0 nearest the processor. Devices 1 and 3 raise requests together.", find: "Who is served, and how far the acknowledge travels.",
      steps: [{ say: "The acknowledge enters device 0, which is not requesting, so it passes it on.", result: "passes device 0" }, { say: "Device 1 is requesting, so it keeps the acknowledge.", result: "device 1 wins" }, { say: "Device 3 waits until device 1 has finished and withdrawn its request.", result: "device 3 waits" }],
      answer: "Device 1 is served first; the acknowledge passes only devices 0 and 1.", check: "Toggle the devices in the arbitration lab." },
    { type: "example", id: "ex3", level: "edge", title: "The most interrupts a CPU can take", given: "A 500 MHz CPU needs 500 cycles for each interrupt, including the handler.", find: "The maximum interrupt rate, and what a device that interrupts 2 million times a second does.",
      steps: [{ say: "Ceiling = 500,000,000 / 500.", result: "1,000,000 / s" }, { say: "At 2,000,000 interrupts a second the handler alone would need 200% of the CPU.", result: "impossible" }],
      answer: "At most 1,000,000 interrupts a second; a device needing 2 million must use DMA or bigger chunks.", check: "Doubling the chunk halves the interrupt rate." },
    { type: "lab", lab: "io-daisy" },
    { type: "faded", title: "Your turn", given: "A 200 MHz CPU services a device by interrupt: 100,000 interrupts a second, 800 cycles each, the device busy 10% of the time.", steps: [{ say: "Cycles per second while busy?", blank: true, answer: "100,000 × 800 = 80 million." }, { say: "CPU fraction while busy?", blank: true, answer: "80 M / 200 M = 40%." }, { say: "Average fraction?", blank: true, answer: "10% × 40% = 4%." }] },
    { type: "trap", wrong: "The processor stops the instant an interrupt arrives.", tempting: "Interrupts are urgent.", whyWrong: "It finishes the current instruction first (and checks the mask), so that the saved state is consistent.", rule: "Interrupts are taken between instructions." },
    { type: "trap", wrong: "In a daisy chain the device farthest from the processor has the highest priority.", tempting: "It is the last to be asked.", whyWrong: "The acknowledge reaches the nearest device first and it keeps it if it is requesting, so the nearest has the highest priority.", rule: "Nearest the CPU = highest priority." },
    { type: "trap", wrong: "A masked interrupt is lost.", tempting: "The CPU ignores it.", whyWrong: "A masked interrupt stays pending at the device or controller and is served when it is unmasked (unless the device withdraws it).", rule: "Masking delays; it does not discard." },
    { type: "shortcut", text: "Interrupt cost = (rate × cycles) / clock × (busy fraction). Ceiling = clock / cycles per interrupt. Daisy chain: the first requesting device along the chain wins.", validWhen: "Constant handler cost; one request per chunk." },
    { type: "gate", text: "GATE asks for the CPU time spent on interrupt-driven I/O, the steps of interrupt handling and what is saved, the priority of devices on a daisy chain, vectored against non-vectored interrupts, and what a mask does. Interrupt questions appear regularly." },
    { type: "recall", cards: [{ q: "Interrupt taken", a: "after the current instruction completes" }, { q: "Saved on an interrupt", a: "PC and status" }, { q: "Vectored", a: "device supplies the handler number" }, { q: "Daisy chain priority", a: "nearest the CPU wins" }, { q: "NMI", a: "non-maskable: cannot be disabled" }] },
    { type: "check", questions: [
      { id: "in1", kind: "NAT", marks: 1, q: "A 500 MHz CPU needs 500 cycles per interrupt. What is the greatest number of interrupts per second it can handle (in thousands)?", answer: "1000", solution: "500,000,000 / 500 = 1,000,000." },
      { id: "in2", kind: "NAT", marks: 2, q: "A disk delivers 4 MB/s in 16-byte chunks, one 500-cycle interrupt per chunk, on a 500 MHz CPU. What percentage of the CPU is used while the disk is transferring?", answer: "25", solution: "250,000 × 500 / 500 M." },
      { id: "in3", kind: "NAT", marks: 2, q: "The same disk is active only 5% of the time. What is the average CPU percentage (two decimals)?", answer: "1.25", solution: "5% of 25%." },
      { id: "in4", kind: "NAT", marks: 1, q: "Four devices 0 to 3 are daisy-chained, device 0 nearest the CPU. Devices 1 and 3 request together. Which device is served first?", answer: "1", solution: "The acknowledge stops at device 1." },
      { id: "in5", kind: "MSQ", marks: 2, q: "Which statements about interrupts are true?", options: ["The CPU completes the current instruction before taking one", "A vectored interrupt supplies the handler number", "A non-maskable interrupt can be disabled by the mask", "The PC and status are saved so that the program can resume"], answer: "A, B, D", solution: "A non-maskable interrupt cannot be disabled by the ordinary mask." },
    ] },
    { type: "practice", links: [{ label: "Real GATE questions on Computer Organisation", sub: "Interrupts", href: TP }, { label: "Topic 1: I/O organisation", sub: "Polling cost", href: HREF }, { label: "Topic 3: DMA", sub: "Modes and cost", href: HREF }] },
    { type: "links", prereq: ["The I/O interface", "The stack"], usedIn: ["DMA completion", "System calls and traps (OS)"], cross: ["OS: interrupts, system calls and context switches"] },
  ],
};

/* ------------------------------------------------------------------ 3. DMA */
const dmaT: Topic = {
  id: "cs.coa.dma",
  title: "Direct memory access: the controller, the modes and the cost",
  blocks: [
    { type: "hook", text: "Moving a megabyte from a disk to memory by interrupts means a million handler runs, each costing hundreds of cycles. But all the processor does in each of them is copy a word. DMA removes the middleman: a small controller is told where to put the block and how big it is, copies the whole block itself across the bus, and rings the processor only when it is done." },
    { type: "objectives", items: ["List the registers of a DMA controller and the steps of a transfer.", "Distinguish burst, cycle-stealing and transparent DMA.", "Compute the CPU cost of DMA and the share of memory cycles a device steals.", "Explain bus arbitration between the CPU and the DMA controller."] },
    { type: "intuition", paras: ["A DMA controller is a simple processor that can only move data. To start a transfer the CPU writes into its registers: the starting memory address, the number of words (the count), and a control word giving the direction (read or write) and starting it. The controller then asks for the bus, takes it when the CPU releases it, and moves one word, or a whole block, between the device and memory, increasing the address and decreasing the count each time. When the count reaches zero it interrupts the CPU. The CPU only runs two small pieces of code per block: the set-up and the completion handler.", "The bus has to be shared. The CPU is normally the bus master; the controller sends a bus request (BR, or HOLD) and when the CPU grants it (BG, or HLDA) at the end of a bus cycle, the controller becomes bus master for as long as it needs. The processor is free to compute with its registers and cache meanwhile, but if it needs memory it must wait.", "How much of the bus the DMA takes defines the mode. In burst (block) mode it keeps the bus for the whole block, which is fast for the device but locks the CPU out of memory for the duration. In cycle-stealing mode it takes the bus for one cycle per word and gives it back, interleaving with the CPU, so the CPU is slowed a little all the time. In transparent mode it uses only the cycles in which the CPU is not using the bus, costing the CPU nothing but needing to know when the bus is free."] },
    { type: "definition", name: "DMA", text: "A transfer of a block between a device and memory:", items: ["Controller registers: memory address, word count, control/status. Optional: device address, mode.", "Steps: (1) CPU programs the controller; (2) the device is ready and the controller requests the bus; (3) the CPU grants the bus; (4) the controller moves the data and updates address and count; (5) at count = 0 the controller interrupts the CPU.", "Burst mode: one bus tenure for the whole block; the CPU is locked out for blocksize × memory cycle. Cycle stealing: one cycle per word. Transparent: only idle bus cycles.", "CPU cost = (blocks per second) × (set-up cycles + completion-interrupt cycles) / clock.", "Fraction of memory cycles stolen = (words per second × memory cycle time)."] },
    { type: "deep", sections: [
      { h: "The cost of DMA", paras: ["The disk delivering 4 MB/s, now using DMA with blocks of 8 KB. There are 4,000,000 / 8,192 = 488.28 blocks a second. If setting up a transfer takes 1000 cycles and the completion interrupt 500 cycles, the CPU spends 488.28 × 1500 = 732,422 cycles a second, which is 0.146% of a 500 MHz processor, and 0.0073% if the disk is busy only 5% of the time. Compare 20% for polling and 25% (1.25% at 5%) for interrupts: DMA is two orders of magnitude cheaper. The larger the block, the fewer the interrupts and the cheaper it becomes.", "DMA's cost is not zero in another way: the DMA and the CPU compete for the memory and the bus, as the next calculation shows."] },
      { h: "Cycle stealing", paras: ["A device moves 1 MB/s in 2-byte words, so 500,000 words a second. The memory cycle is 500 ns, so memory can do 2,000,000 cycles a second. The DMA takes 500,000 × 500 ns = 0.25 s of every second: 25% of the memory cycles. The CPU is left with 75% of the memory bandwidth, and slows down only if its own demand for memory is more than that, which, thanks to the cache, it often is not.", "A faster device: 4 MB/s in 4-byte words with a 100 ns memory cycle needs 1,000,000 words a second × 100 ns = 10% of the memory cycles.", "Burst mode takes the same total time (a block of 1024 words at 100 ns needs 102.4 µs of memory time) but all at once: the processor cannot reach memory for 102.4 µs. For a device that cannot wait (it must empty a buffer before it overflows) that is the right trade; for a CPU running real-time code it may not be."] },
      { h: "Caches, channels and the OS", paras: ["DMA writes to memory without going through the cache, so the cache can hold stale data (the old contents of a buffer the DMA has just overwritten) and memory can hold stale data (a cached write not yet written back, which the DMA then reads). The system must flush or invalidate the cache lines around a DMA buffer, or use hardware coherence.", "A more powerful form is the I/O channel (or I/O processor): a DMA controller that can follow a small program of its own (chains of transfers, error handling, format conversion), used in mainframes. Operating systems submit I/O requests to the driver, which programs the DMA and sleeps the requesting process until the completion interrupt."] },
    ] },
    { type: "walkthrough", steps: ["Find the number of blocks per second: byte rate / block size.", "CPU cost = blocks per second × (set-up + completion cycles) / clock, times the busy fraction.", "For cycle stealing: words per second × memory cycle time = fraction of memory cycles taken.", "For burst mode: block words × memory cycle time = time the CPU is locked out.", "Check that the memory can supply the device's rate: the stolen fraction must be below 100%."], prompt: { q: "How many times does the CPU get involved in a DMA transfer of one block?", a: "Twice: once to set up the transfer, and once in the interrupt handler when it completes." } },
    { type: "figure", id: "dma-tbl", for: "ex1", caption: "The same 4 MB/s disk by the three methods (500 MHz CPU).", alt: "Polling 20 percent; interrupts 25 percent while active, 1.25 percent at 5 percent busy; DMA 0.146 percent while active and 0.0073 percent at 5 percent.", fig: { kind: "matrix", title: "CPU used", cols: ["while active", "busy 5% of the time"], rows: [{ label: "Polling", cells: ["20%", "20%"] }, { label: "Interrupts", cells: ["25%", "1.25%"] }, { label: "DMA (8 KB blocks)", cells: ["0.146%", "0.0073%"], hl: true }] } },
    { type: "figure", id: "mode-tbl", for: "ex2", caption: "The three DMA modes.", alt: "Burst: one tenure for the whole block, CPU locked out. Cycle stealing: one cycle per word. Transparent: only idle cycles, no slowdown.", fig: { kind: "matrix", title: "DMA modes", cols: ["bus use", "effect on the CPU"], rows: [{ label: "Burst (block)", cells: ["whole block at once", "locked out for the block"] }, { label: "Cycle stealing", cells: ["one cycle per word", "slowed slightly, all the time"], hl: true }, { label: "Transparent", cells: ["idle cycles only", "none, needs hardware to find them"] }] } },
    { type: "example", id: "ex1", level: "gate", title: "DMA against interrupts", given: "A 500 MHz CPU. A disk delivers 4 MB/s; DMA uses 8 KB blocks; set-up takes 1000 cycles and the completion interrupt 500 cycles.", find: "The CPU fraction used by DMA.",
      steps: [{ say: "Blocks per second = 4,000,000 / 8192.", result: "488.28" }, { say: "Cycles per second = 488.28 × 1500.", result: "732,422" }, { say: "Fraction = 732,422 / 500,000,000.", result: "0.146%" }],
      answer: "0.146% of the CPU (against 20% for polling and 25% for interrupts).", check: "Set the DMA block to 8192 in the lab." },
    { type: "example", id: "ex2", level: "gate", title: "Cycle stealing", given: "A DMA device moves 1 MB/s in 2-byte words. The memory cycle is 500 ns.", find: "The share of memory cycles used, and the CPU lock-out for a burst of 1024 words at a 100 ns cycle.",
      steps: [{ say: "Words per second = 500,000; time per second = 500,000 × 500 ns.", result: "0.25 s" }, { say: "That is 25% of the memory cycles.", result: "25%" }, { say: "Burst: 1024 × 100 ns.", result: "102.4 µs" }],
      answer: "25% of the memory cycles; a 102.4 µs lock-out for the burst.", check: "Try 4 MB/s, 4-byte words, 100 ns: 10%." },
    { type: "example", id: "ex3", level: "edge", title: "When the memory cannot keep up", given: "A device moves 8 MB/s in 1-byte words. The memory cycle is 200 ns.", find: "Whether cycle stealing can keep up.",
      steps: [{ say: "Words per second = 8,000,000; time = 8,000,000 × 200 ns = 1.6 s per second.", result: "160%" }, { say: "More than 100% of the memory cycles are needed.", result: "impossible" }],
      answer: "No: 160% of the memory cycles. A wider transfer (4-byte words: 40%) or a faster memory is needed.", check: "Widening the DMA word is the cheapest fix." },
    { type: "lab", lab: "io-dma" },
    { type: "faded", title: "Your turn", given: "A DMA device moves 2 MB/s in 4-byte words; the memory cycle is 250 ns. A 2048-word burst is considered.", steps: [{ say: "Words per second?", blank: true, answer: "500,000." }, { say: "Share of memory cycles?", blank: true, answer: "500,000 × 250 ns = 12.5%." }, { say: "CPU lock-out for the burst?", blank: true, answer: "2048 × 250 ns = 512 µs." }] },
    { type: "trap", wrong: "DMA needs no CPU involvement at all.", tempting: "The controller does the copy.", whyWrong: "The CPU sets up each transfer and handles the completion interrupt; and it may be slowed by bus sharing.", rule: "DMA: two CPU interventions per block." },
    { type: "trap", wrong: "Cycle stealing and burst mode take different total memory time.", tempting: "One is slower.", whyWrong: "For the same data they use the same memory time; cycle stealing spreads it out, burst mode puts it in one block.", rule: "Same total time; different timing." },
    { type: "trap", wrong: "A DMA transfer needs no cache care.", tempting: "It is hardware doing the copy.", whyWrong: "DMA bypasses the cache, so the cache can hold stale data; the buffer must be flushed or invalidated.", rule: "DMA and caches need coherence." },
    { type: "shortcut", text: "DMA CPU cost = (rate / block) × (set-up + completion) / clock. Cycle stealing share = (rate / word) × memory cycle. Burst lock-out = block words × memory cycle.", validWhen: "Single device, constant rate, the CPU stalls only when it needs memory during the DMA cycles." },
    { type: "gate", text: "GATE asks for the CPU time of DMA transfers, the percentage of memory cycles stolen by a DMA device, the lock-out in burst mode, the steps of a DMA transfer, and which mode suits which device. DMA calculations are common in the I/O questions." },
    { type: "recall", cards: [{ q: "DMA registers", a: "address, word count, control" }, { q: "DMA ends with", a: "an interrupt to the CPU" }, { q: "Burst mode", a: "whole block at once, CPU locked out" }, { q: "Cycle stealing", a: "one memory cycle per word" }, { q: "Bus handshake", a: "bus request, bus grant" }] },
    { type: "check", questions: [
      { id: "dm1", kind: "NAT", marks: 2, q: "A DMA device moves 1 MB/s in 2-byte words and the memory cycle is 500 ns. What percentage of the memory cycles does it steal?", answer: "25", solution: "500,000 words/s × 500 ns = 0.25." },
      { id: "dm2", kind: "NAT", marks: 2, q: "A 500 MHz CPU has a disk delivering 4 MB/s by DMA in 8 KB blocks (8192 bytes), with 1000 set-up and 500 completion cycles. What percentage of the CPU is used (three decimals)?", answer: "0.146", solution: "488.28 × 1500 / 500 M." },
      { id: "dm3", kind: "NAT", marks: 2, q: "A burst of 1024 words uses a memory cycle of 100 ns. For how many microseconds is the CPU locked out of memory?", answer: "102.4", solution: "1024 × 100 ns." },
      { id: "dm4", kind: "NAT", marks: 1, q: "How many times does the CPU intervene in the transfer of one block by DMA?", answer: "2", solution: "Set-up and completion interrupt." },
      { id: "dm5", kind: "MSQ", marks: 2, q: "Which statements about DMA are true?", options: ["The controller interrupts the CPU when the count reaches zero", "In cycle stealing mode the DMA takes one memory cycle per word", "DMA needs no registers", "DMA bypasses the cache"], answer: "A, B, D", solution: "The DMA controller has address, count and control registers." },
    ] },
    { type: "practice", links: [{ label: "Real GATE questions on Computer Organisation", sub: "DMA", href: TP }, { label: "Topic 2: interrupts", sub: "Handling and priority", href: HREF }, { label: "Topic 4: buses and arbitration", sub: "Bandwidth", href: HREF }] },
    { type: "links", prereq: ["Interrupts", "Memory cycle time"], usedIn: ["Device drivers (OS)", "Cache coherence"], cross: ["OS: I/O scheduling and buffering"] },
  ],
};

/* ------------------------------------------------------------------ 4. Buses */
const busT: Topic = {
  id: "cs.coa.bus",
  title: "Buses: synchronous and asynchronous transfer, bandwidth and arbitration",
  blocks: [
    { type: "hook", text: "Everything so far, the processor, the memory, the devices and the DMA controller, meets on a bus: a set of wires they share. Sharing is cheap, but two things have to be settled for it to work: how a transfer is timed, and who may speak when several want to at once." },
    { type: "objectives", items: ["Describe the address, data and control lines of a bus and the roles of master and slave.", "Compare synchronous and asynchronous (handshake) transfer.", "Compute the bandwidth of a bus for a given width, clock and transaction.", "Compare daisy-chain, centralised-parallel and distributed arbitration."] },
    { type: "intuition", paras: ["A bus has three groups of lines: address lines (which location), data lines (the value), and control lines (read or write, ready, request, grant, clock). At any moment one device, the bus master, controls the transfer, and another, the slave, responds. The processor is a master; memory is a slave; a DMA controller can be a master too.", "In a synchronous bus a clock is part of the bus, and every action takes place at agreed clock edges: the master puts the address on the bus in cycle 1, the slave must have the data ready by cycle 3. It is simple and fast, but all the devices must run at the clock's speed, and the bus has to be short enough that signals arrive within a cycle. In an asynchronous bus there is no common clock; the master and slave coordinate with a handshake, two control lines (for example ReadReq and Ack). The master raises ReadReq with the address; the slave, when it has the data, puts it on the bus and raises Ack; the master reads it and lowers ReadReq; the slave lowers Ack. Each step waits for the previous one, so the bus adapts to the speed of whichever device is slow, but every transfer costs the extra handshake delays.", "When more than one device may become master, an arbiter decides who gets the bus. The scheme has to be fair enough that nobody starves, quick enough not to waste bus time, and cheap."] },
    { type: "definition", name: "Bus bandwidth and arbitration", text: "For a bus W bits wide at f MHz:", items: ["Peak bandwidth = (W / 8) bytes × f million transfers a second.", "A transaction that moves w words in w + o cycles (o = address and other overhead cycles) delivers (W / 8) × w × f / (w + o) bytes a second; longer bursts amortise the overhead.", "Synchronous bus: common clock, fixed timing. Asynchronous bus: handshake on request and acknowledge lines, no clock.", "Daisy-chain arbitration: a grant line passes from device to device; fixed priority by position; few lines. Centralised parallel (independent requests): each device has its own request and grant line to one arbiter; fast, flexible priority, more lines. Distributed arbitration: no arbiter; devices put their codes on shared lines and the highest wins (self-selection), or poll in turn.", "Split-transaction (pipelined) bus: the address and the reply are separate transactions, so the bus is free while the memory is busy."] },
    { type: "deep", sections: [
      { h: "Bandwidth worked out", paras: ["A 32-bit bus at 100 MHz moves 4 bytes every 10 ns, a peak of 400 MB/s. If every word needs its own address cycle (address and data share the same lines, one cycle each), a transfer takes 2 cycles and the bandwidth halves to 200 MB/s. If the bus can send a burst of 8 words after one address cycle, 8 words take 9 cycles: 32 bytes in 90 ns, 355.6 MB/s, almost 89% of the peak. A wider bus (64 bits) or a faster clock raises the peak; a burst raises the efficiency."] },
      { h: "The handshake in detail", paras: ["A four-phase read on an asynchronous bus: (1) the master puts the address on the bus and asserts ReadReq. (2) The slave sees it, reads the address, fetches the data, puts it on the data lines and asserts DataReady (Ack). (3) The master sees DataReady, reads the data, and deasserts ReadReq. (4) The slave sees ReadReq drop and deasserts DataReady, ready for the next transfer. Each of the four steps waits for the previous one, so a slow slave simply takes longer, and a fast one is not held back by a clock that is slower than it needs.", "A single strobe (no acknowledge) is simpler but the master cannot know that the slave heard it, so it is only safe when the slave is known to be fast enough. The handshake (strobe and acknowledge) also makes it possible to detect a slave that never replies (time-out)."] },
      { h: "Arbitration compared", paras: ["Daisy chain: one bus-request line shared by all, and a bus-grant line that passes from the arbiter through each device in turn. The first requesting device keeps the grant. Cheap (three wires however many devices), but priority is fixed by position, the grant must ripple through every device (slow for long chains), and a failed device breaks the chain.", "Centralised parallel: every device has a request and a grant line to the arbiter, which can apply any rule (fixed priority, rotating priority, first come first served). Fast and flexible, but needs 2N lines and a bigger arbiter.", "Distributed: no central arbiter. In self-selection each device places its priority code on shared arbitration lines and the highest wins; in rotating polling a counter steps through the devices starting after the last winner, so every device gets its turn."] },
    ] },
    { type: "walkthrough", steps: ["Count bytes per transfer: the bus width divided by 8.", "Find the cycles of a transaction: the words moved plus any address or arbitration cycles.", "Bandwidth = bytes per transaction / (cycles × clock period).", "For arbitration, find the requesting devices and apply the rule: nearest in the chain, or the arbiter's priority.", "Check which devices could starve under a fixed-priority rule."], prompt: { q: "Why does a burst raise the delivered bandwidth of a bus?", a: "The address cycle is paid once for several words, so a larger share of the cycles moves data." } },
    { type: "figure", id: "bus-tbl", for: "ex1", caption: "A 32-bit, 100 MHz bus under three transaction patterns.", alt: "A word a cycle gives 400 MB/s; an address cycle per word 200 MB/s; 8-word bursts with one address cycle 355.6 MB/s.", fig: { kind: "matrix", title: "Bandwidth", cols: ["cycles per transaction", "MB/s"], rows: [{ label: "Data every cycle (peak)", cells: [1, 400] }, { label: "1 address + 1 data cycle", cells: [2, 200] }, { label: "1 address + 8 data cycles", cells: [9, 355.6], hl: true }] } },
    { type: "figure", id: "arb-tbl", for: "ex2", caption: "Three ways to decide who gets the bus.", alt: "Daisy chain: three wires, fixed priority. Centralised parallel: 2N lines, any priority rule. Distributed: no arbiter, codes or rotating polling.", fig: { kind: "matrix", title: "Arbitration", cols: ["lines", "priority", "weakness"], rows: [{ label: "Daisy chain", cells: ["3, whatever N", "fixed by position", "starvation, slow ripple, one failure breaks it"], hl: true }, { label: "Centralised parallel", cells: ["2N", "any rule", "more wires, bigger arbiter"] }, { label: "Distributed", cells: ["a few shared", "code or rotating", "more complex devices"] }] } },
    { type: "example", id: "ex1", level: "gate", title: "Bus bandwidth", given: "A 32-bit bus runs at 100 MHz.", find: "The bandwidth when data moves every cycle, when each word needs an address cycle, and for 8-word bursts with one address cycle.",
      steps: [{ say: "4 bytes every 10 ns.", result: "400 MB/s" }, { say: "2 cycles per word: 4 bytes in 20 ns.", result: "200 MB/s" }, { say: "8 words in 9 cycles: 32 bytes in 90 ns.", result: "355.6 MB/s" }],
      answer: "400, 200 and 355.6 MB/s.", check: "Enter 32, 100, 8, 1 in the bus bandwidth lab." },
    { type: "example", id: "ex2", level: "gate", title: "Who gets the bus", given: "Four bus masters on a daisy chain request together; M0 is nearest the arbiter.", find: "The order in which they are served, if each keeps requesting as soon as it finishes.",
      steps: [{ say: "The grant reaches M0 first, so M0 wins.", result: "M0" }, { say: "M0 requests again at once and wins again: the grant never reaches the others.", result: "starvation" }],
      answer: "M0 is served over and over; M1 to M3 starve. A rotating priority (or a limit on the length of a tenure) is needed.", check: "Compare with the rotating poll in the arbitration lab." },
    { type: "example", id: "ex3", level: "edge", title: "A slow slave", given: "A memory takes 5 cycles to respond on a synchronous bus designed for 2 cycles.", find: "What a designer can do.",
      steps: [{ say: "On a synchronous bus the master cannot know the slave is slow, so the data would be read too early.", result: "wrong data" }, { say: "Insert wait states (a ready line the slave holds low), or use an asynchronous handshake.", result: "wait states" }],
      answer: "Add wait states with a ready signal, or use a handshake: the master waits until the slave says the data are valid.", check: "A handshake bus adapts to each slave; a synchronous bus pays for the slowest by wait states." },
    { type: "lab", lab: "io-bus" },
    { type: "faded", title: "Your turn", given: "A 64-bit bus at 200 MHz moves 4 words per transaction, with 2 overhead cycles per transaction.", steps: [{ say: "Peak bandwidth?", blank: true, answer: "8 bytes × 200 M = 1600 MB/s." }, { say: "Delivered bandwidth?", blank: true, answer: "32 bytes in 6 cycles = 32 / 30 ns = 1066.7 MB/s." }, { say: "Efficiency?", blank: true, answer: "4/6 = 66.7%." }] },
    { type: "trap", wrong: "An asynchronous bus is always faster than a synchronous one.", tempting: "It has no clock to wait for.", whyWrong: "Each handshake step adds delay; its benefit is flexibility with devices of different speeds, not speed.", rule: "Synchronous = fast and simple; asynchronous = flexible." },
    { type: "trap", wrong: "A daisy chain needs one grant line per device.", tempting: "Each device is granted separately.", whyWrong: "There is a single grant line that passes through the devices; that is why it needs few wires. One grant line per device is centralised parallel arbitration.", rule: "Daisy chain: few wires, fixed priority." },
    { type: "trap", wrong: "The bandwidth of a bus is its width times its clock.", tempting: "That is the peak.", whyWrong: "Address and arbitration cycles are overhead; delivered bandwidth is lower unless bursts amortise them.", rule: "Delivered = bytes moved / total time including overhead." },
    { type: "shortcut", text: "Bandwidth = (W/8) × words × f / (words + overhead cycles). Daisy chain: nearest wins. Parallel arbitration: 2N lines. Handshake: request, acknowledge, release, release.", validWhen: "One master at a time; overhead cycles fixed per transaction." },
    { type: "gate", text: "GATE asks for the bandwidth or the time of a transfer over a bus, the difference between synchronous and asynchronous transfer, the steps of a handshake, and the arbitration schemes: which device wins, the number of lines, and the weaknesses of each." },
    { type: "recall", cards: [{ q: "Bus master", a: "the device controlling the transfer" }, { q: "Synchronous bus", a: "common clock, fixed timing" }, { q: "Asynchronous bus", a: "handshake (request / acknowledge)" }, { q: "Peak bandwidth", a: "width / 8 × clock" }, { q: "Daisy-chain arbitration", a: "one grant line, fixed priority" }] },
    { type: "check", questions: [
      { id: "bu1", kind: "NAT", marks: 1, q: "A 32-bit bus runs at 100 MHz and moves one word every cycle. What is the bandwidth in MB/s?", answer: "400", solution: "4 bytes × 100 M." },
      { id: "bu2", kind: "NAT", marks: 2, q: "On the same bus every word needs one address cycle and one data cycle. What is the bandwidth in MB/s?", answer: "200", solution: "4 bytes per 2 cycles." },
      { id: "bu3", kind: "NAT", marks: 2, q: "On the same bus, 8-word bursts follow one address cycle. What is the bandwidth in MB/s (one decimal)?", answer: "355.6", solution: "32 bytes in 9 cycles of 10 ns." },
      { id: "bu4", kind: "MCQ", marks: 1, q: "In daisy-chain bus arbitration, the device with the highest priority is", options: ["The farthest from the arbiter", "The nearest to the arbiter", "The one with the largest address", "Chosen at random"], answer: "B", solution: "The grant reaches it first." },
      { id: "bu5", kind: "MSQ", marks: 2, q: "Which statements are true?", options: ["A synchronous bus uses a common clock", "An asynchronous bus uses a handshake", "Centralised parallel arbitration needs a request and grant line per device", "A daisy chain cannot starve a low-priority device"], answer: "A, B, C", solution: "A fixed-priority daisy chain can starve devices far from the arbiter." },
    ] },
    { type: "practice", links: [{ label: "Real GATE questions on Computer Organisation", sub: "Buses and arbitration", href: TP }, { label: "Topic 3: DMA", sub: "Cycle stealing", href: HREF }, { label: "Topic 1: I/O organisation", sub: "Polling cost", href: HREF }] },
    { type: "links", prereq: ["DMA", "Memory cycle"], usedIn: ["Memory systems", "I/O buses (PCI, USB)"], cross: ["CN: shared media and arbitration", "OS: device drivers"] },
  ],
};

